package com.ebuddy.repo; import com.ebuddy.domain.MessageEntity; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.Pageable; import java.util.*; public interface MessageRepository extends JpaRepository<MessageEntity,UUID>{Optional<MessageEntity> findBySenderUserIdAndClientMessageId(UUID sender,String clientId); @Query("select m from MessageEntity m where m.sequence > :cursor and (m.senderUserId=:user or m.recipientUserId=:user) order by m.sequence asc") List<MessageEntity> findAfter(@Param("user")UUID user,@Param("cursor")long cursor,Pageable pageable); @Query("select m from MessageEntity m where m.id=:id and (m.senderUserId=:user or m.recipientUserId=:user)") Optional<MessageEntity> findVisible(@Param("id")UUID id,@Param("user")UUID user);}
